#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
vector<string> split_tab(const string& s){
 vector<string> v; size_t a=0;
 while(true){size_t b=s.find('\t',a); if(b==string::npos){v.push_back(s.substr(a));break;} v.push_back(s.substr(a,b-a));a=b+1;}
 return v;
}
string collapse(string x){
 if(x=="epidermal_neural1"||x=="epidermal_neural2") return "epidermal_neural";
 if(x=="epidermis_1"||x=="epidermis_2") return "epidermis";
 if(x=="neural_like1"||x=="neural_like2") return "neural_like";
 return x;
}
double cor(const vector<double>& a,const vector<double>& b){
 double ma=0,mb=0; int n=a.size(); for(int i=0;i<n;i++){ma+=a[i];mb+=b[i];}ma/=n;mb/=n;
 double va=0,vb=0,co=0;for(int i=0;i<n;i++){double x=a[i]-ma,y=b[i]-mb;va+=x*x;vb+=y*y;co+=x*y;}
 return (va>0&&vb>0)?co/sqrt(va*vb):0;
}
int main(int argc,char**argv){
 string qpath=argv[1],cpath=argv[2],apath=argv[3],opath=argv[4],line;
 vector<string> labels; unordered_map<string,vector<double>> query;
 ifstream qf(qpath); getline(qf,line); auto qh=split_tab(line); for(size_t i=1;i<qh.size();i++) labels.push_back(qh[i]);
 while(getline(qf,line)){auto t=split_tab(line);if(t.size()<labels.size()+1)continue;vector<double>x(labels.size());for(size_t i=0;i<labels.size();i++)x[i]=stod(t[i+1]);query[t[0]]=move(x);}
 unordered_map<string,string> ctype; ifstream af(apath); getline(af,line);
 while(getline(af,line)){auto t=split_tab(line);if(t.size()>=2)ctype[t[0]]=t[1];}
 unordered_map<string,int> li;for(size_t i=0;i<labels.size();i++)li[labels[i]]=i;
 ifstream cf(cpath);getline(cf,line);auto hh=split_tab(line);
 vector<int> g_ex(hh.size(),-1),g_in(hh.size(),-1); vector<long long> nc_ex(labels.size()),nc_in(labels.size());
 for(size_t i=1;i<hh.size();i++){
   auto it=ctype.find(hh[i]); if(it==ctype.end())continue; string x=collapse(it->second);
   if(x=="DiMes"||x=="HyTh"){auto z=li.find("neural");if(z!=li.end()){g_in[i]=z->second;nc_in[z->second]++;}continue;}
   auto z=li.find(x);if(z!=li.end()){g_ex[i]=g_in[i]=z->second;nc_ex[z->second]++;nc_in[z->second]++;}
 }
 vector<long long> tot_ex(labels.size()),tot_in(labels.size());
 struct Sums{vector<long long> ex,in;};unordered_map<string,Sums> sums;sums.reserve(query.size()*2);
 long long rows=0,matched=0;
 while(getline(cf,line)){
   size_t p=line.find('\t');if(p==string::npos)continue;string gene=line.substr(0,p); bool keep=query.find(gene)!=query.end();
   vector<long long> sx(labels.size()),si(labels.size()); size_t idx=1,start=p+1; long long val=0; bool any=false;
   for(size_t k=start;k<=line.size();k++){
     char ch=(k<line.size()?line[k]:'\t');
     if(ch>='0'&&ch<='9'){val=val*10+(ch-'0');any=true;}
     else if(ch=='\t'){
       if(idx<g_ex.size()&&any){
         int a=g_ex[idx],b=g_in[idx];if(a>=0){tot_ex[a]+=val;if(keep)sx[a]+=val;}if(b>=0){tot_in[b]+=val;if(keep)si[b]+=val;}
       }
       idx++;val=0;any=false;
     }
   }
   if(keep){sums[gene]={move(sx),move(si)};matched++;}rows++;
 }
 ofstream out(opath);out<<"section\tvariant\tobserved\treference\tvalue\tdetail\n";
 out<<"qc\tboth\tgenes\tmatched\t"<<matched<<"\tcount_rows="<<rows<<";query_genes="<<query.size()<<"\n";
 for(int j=0;j<(int)labels.size();j++)out<<"qc\texclude_DiMes_HyTh\t"<<labels[j]<<"\tcell_count\t"<<nc_ex[j]<<"\ttotal_umi="<<tot_ex[j]<<"\n";
 for(int j=0;j<(int)labels.size();j++)out<<"qc\tmerge_DiMes_HyTh_into_neural\t"<<labels[j]<<"\tcell_count\t"<<nc_in[j]<<"\ttotal_umi="<<tot_in[j]<<"\n";
 vector<string> genes;for(auto &kv:query)if(sums.find(kv.first)!=sums.end())genes.push_back(kv.first);sort(genes.begin(),genes.end());
 for(int variant=0;variant<2;variant++){
   string vn=variant?"merge_DiMes_HyTh_into_neural":"exclude_DiMes_HyTh";
   for(int oi=0;oi<(int)labels.size();oi++){
     vector<pair<double,int>> ranking;
     for(int rj=0;rj<(int)labels.size();rj++){
       vector<double>a,b,al,bl;a.reserve(genes.size());b.reserve(genes.size());al.reserve(genes.size());bl.reserve(genes.size());
       double mae=0,maxerr=0;long long den=variant?tot_in[rj]:tot_ex[rj];
       for(auto &g:genes){
         double x=query[g][oi];long long s=variant?sums[g].in[rj]:sums[g].ex[rj];double y=den?100000.0*s/den:0;
         a.push_back(x);b.push_back(y);al.push_back(log1p(x));bl.push_back(log1p(y));double e=abs(x-y);mae+=e;maxerr=max(maxerr,e);
       }
       double cr=cor(a,b),cl=cor(al,bl);mae/=genes.size();ranking.push_back({cl,rj});
       out<<"correlation_log1p\t"<<vn<<"\t"<<labels[oi]<<"\t"<<labels[rj]<<"\t"<<setprecision(10)<<cl<<"\traw_cor="<<cr<<";mae_cpm="<<mae<<";maxerr="<<maxerr<<"\n";
     }
     sort(ranking.rbegin(),ranking.rend());
     out<<"best_match\t"<<vn<<"\t"<<labels[oi]<<"\t"<<labels[ranking[0].second]<<"\t"<<ranking[0].first<<"\tsecond="<<labels[ranking[1].second]<<":"<<ranking[1].first<<"\n";
   }
 }
}

